using System.Text.Json;
using Jindan.Contracts.Drive;
using Jindan.Infrastructure.Drive;

internal static class Program
{
    static string work = ""; static int pass, fail; static readonly List<object> results = [];
    static readonly DriveScope Scope = new("synthetic-user", "synthetic-project", "fixture-root");
    static string Folder() { var path = Path.Combine(work, Guid.NewGuid().ToString("N")); Directory.CreateDirectory(path); return path; }
    static OfflineDriveFixture Fixture() => new(1, Scope, [new(Scope, Scope.RootId, [new("sub", "Reports", DriveEntry.FolderMime), new("body", "report.pdf", "application/pdf", 123), new("hidden", ".SYSTEM", DriveEntry.FolderMime)]), new(Scope, "sub", [new("text", "note.txt", "text/plain", 8)]), new(Scope, "hidden", [])]);
    static OfflineDriveTransport Fake() => new(Fixture(), true);
    static void Assert(bool condition, string message) { if (!condition) throw new Exception(message); }
    static async Task Expect(string code, Func<Task> action) { try { await action(); } catch (DriveBoundaryException e) { Assert(e.Code == code, $"Expected {code}, got {e.Code}"); return; } throw new Exception("Expected " + code); }
    static async Task Cancelled(Task task) { try { await task; } catch (OperationCanceledException) { return; } throw new Exception("Expected cancellation"); }
    static async Task Test(string name, Func<Task> action) { try { await action(); pass++; results.Add(new { name, passed = true }); Console.WriteLine("PASS " + name); } catch (Exception e) { fail++; results.Add(new { name, passed = false, error = e.GetType().Name, message = e.Message }); Console.WriteLine("FAIL " + name + ": " + e.Message); } }
    static async Task<int> Main()
    {
        var root = AppContext.BaseDirectory; while (!File.Exists(Path.Combine(root, "Directory.Build.props"))) root = Path.GetDirectoryName(root) ?? throw new Exception("Root missing"); work = Path.Combine(root, "artifacts", "drive70", DateTime.UtcNow.ToString("yyyyMMddTHHmmss") + "-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(work);
        await Test("construction performs no listing or mutations and production remains NotConfigured", async () => { var p = Fake(); using var cache = new DriveListingCache(Folder(), Scope, p); var system = new OfflineDriveSystem(Scope, p, true); Assert(p.ReadCalls == 0 && p.Mutations == 0 && cache.ReadSnapshot().Count == 0, "Startup had side effects"); await Expect("DRIVE_NOT_CONFIGURED", () => new NotConfiguredDriveProvider().ListAsync(Scope, Scope.RootId, default)); await Expect("DRIVE_SYSTEM_OFFLINE_ONLY", () => Task.Run(() => new OfflineDriveSystem(Scope, new NonFixture(), true))); });
        await Test("fixture opt-in and scope/path guards precede transport", async () => { await Expect("DRIVE_FIXTURE_OPT_IN", () => Task.Run(() => new OfflineDriveTransport(Fixture(), false))); await Expect("DRIVE_ID", () => Task.Run(() => new DriveListingCache(Folder(), Scope with { RootId = "../outside" }, Fake()))); await Expect("DRIVE_PROTECTED_PATH", () => Task.Run(() => new DriveListingCache("F:/jindan/forbidden-drive-cache", Scope, Fake()))); await Expect("DRIVE_SCOPE_DENIED", () => Fake().ListAsync(Scope with { UserId = "other" }, Scope.RootId, default)); });
        await Test("bounded tree warms without hidden system entries or content downloads", async () => { var p = Fake(); using var cache = new DriveListingCache(Folder(), Scope, p); await cache.WarmAsync(); Assert(cache.ReadSnapshot().Count == 2 && p.ReadCalls == 2 && p.Mutations == 0 && cache.ReadSnapshot().All(x => x.Entries.All(DriveBoundary.Visible)), "Tree or hidden entries incorrect"); Assert(cache.Status.IsSynthetic && cache.Status.Completed == 2 && cache.Status.ErrorCode is null, "Status incorrect"); });
        await Test("persistent cache hydrates immediately without provider calls across fresh instance", async () => { var dir = Folder(); using (var cache = new DriveListingCache(dir, Scope, Fake())) await cache.WarmAsync(); var p = Fake(); using var reopened = new DriveListingCache(dir, Scope, p); Assert(reopened.ReadSnapshot().Count == 2 && p.ReadCalls == 0 && reopened.Status.Persistent, "Hydration did network-like reads"); await reopened.WarmAsync(); Assert(p.ReadCalls == 0, "Fresh two-minute TTL ignored"); });
        await Test("expired offline cache stays readable and sanitized error never leaks body", async () => { var now = DateTimeOffset.UtcNow; var p = Fake(); using var cache = new DriveListingCache(Folder(), Scope, p, () => now); await cache.WarmAsync(); now = now.AddMinutes(3); p.BeforeList = (_, _) => Task.FromException(new IOException("PRIVATE DOCUMENT TOKEN")); await cache.WarmAsync(); Assert(cache.ReadSnapshot().Count == 2 && cache.Status.ErrorCode == "DRIVE_LISTING_FAILED", "Offline fallback lost cache or leaked error"); });
        await Test("same-folder refresh coalesces while later cancellation affects only waiter", async () => { var p = Fake(); var entered = new TaskCompletionSource(); var release = new TaskCompletionSource(); p.BeforeList = async (_, ct) => { entered.TrySetResult(); await release.Task.WaitAsync(ct); }; using var cache = new DriveListingCache(Folder(), Scope, p); var first = cache.RefreshAsync(Scope.RootId); await entered.Task; using var ct = new CancellationTokenSource(); var waiter = cache.RefreshAsync(Scope.RootId, true, ct.Token); ct.Cancel(); await Cancelled(waiter); Assert(!first.IsCompleted, "Waiter canceled owner"); release.SetResult(); await first; Assert(p.ReadCalls == 1, "Duplicate provider read"); });
        await Test("invalidation rejects a pre-mutation listing instead of overwriting cache", async () => { var p = Fake(); using var cache = new DriveListingCache(Folder(), Scope, p); await cache.WarmAsync(); var entered = new TaskCompletionSource(); var release = new TaskCompletionSource(); p.BeforeList = async (_, ct) => { entered.TrySetResult(); await release.Task.WaitAsync(ct); }; var old = cache.RefreshAsync(Scope.RootId, true); await entered.Task; cache.Invalidate(Scope.RootId); release.SetResult(); await Expect("DRIVE_STALE_LISTING", () => old); Assert(cache.ReadSnapshot().Count == 2, "Stale listing damaged prior cache"); });
        await Test("owner cancellation and dispose do not publish late provider result", async () => { var p = Fake(); var entered = new TaskCompletionSource(); var release = new TaskCompletionSource(); p.BeforeList = async (_, _) => { entered.TrySetResult(); await release.Task; }; var dir = Folder(); using var cache = new DriveListingCache(dir, Scope, p); using var cancel = new CancellationTokenSource(); var attempt = cache.RefreshAsync(Scope.RootId, true, cancel.Token); await entered.Task; cancel.Cancel(); await Cancelled(attempt); release.SetResult(); await Task.Delay(30); Assert(cache.ReadSnapshot().Count == 0 && !File.Exists(cache.CacheFile), "Late result was committed"); cache.Dispose(); });
        await Test("foreign root/response and unreachable arbitrary folder fail closed", async () => { using var cache = new DriveListingCache(Folder(), Scope, new WrongScope()); await Expect("DRIVE_SCOPE_MISMATCH", () => cache.RefreshAsync(Scope.RootId)); using var good = new DriveListingCache(Folder(), Scope, Fake()); await Expect("DRIVE_FOLDER_SCOPE", () => good.RefreshAsync("foreign-folder")); Assert(good.ReadSnapshot().Count == 0, "Unauthorized folder cached"); });
        await Test("duplicate remote IDs are rejected without partial cache publication", async () => { using var cache = new DriveListingCache(Folder(), Scope, new DuplicateProvider()); await Expect("DRIVE_DUPLICATE", () => cache.RefreshAsync(Scope.RootId)); Assert(cache.ReadSnapshot().Count == 0 && !File.Exists(cache.CacheFile), "Invalid listing published"); });
        await Test("cache scopes isolate same IDs across users projects and roots", async () => { var dir = Folder(); using var a = new DriveListingCache(dir, Scope, Fake()); using var b = new DriveListingCache(dir, Scope with { UserId = "other-user" }, new NotConfiguredDriveProvider()); using var c = new DriveListingCache(dir, Scope with { ProjectId = "other-project" }, new NotConfiguredDriveProvider()); using var d = new DriveListingCache(dir, Scope with { RootId = "other-root" }, new NotConfiguredDriveProvider()); await a.WarmAsync(); Assert(new[] { a.CacheFile, b.CacheFile, c.CacheFile, d.CacheFile }.Distinct().Count() == 4 && b.ReadSnapshot().Count == 0 && c.ReadSnapshot().Count == 0 && d.ReadSnapshot().Count == 0, "Scope cache collision"); });
        await Test("future schema and tampered persisted scope are preserved and rejected", async () => { var dir = Folder(); string file; using (var cache = new DriveListingCache(dir, Scope, Fake())) { await cache.WarmAsync(); file = cache.CacheFile; } var original = await File.ReadAllTextAsync(file); await File.WriteAllTextAsync(file, original.Replace("\"Schema\": 1", "\"Schema\": 2")); var future = await File.ReadAllTextAsync(file); await Expect("DRIVE_CACHE_SCHEMA", () => Task.Run(() => new DriveListingCache(dir, Scope, Fake()))); Assert(await File.ReadAllTextAsync(file) == future, "Future schema overwritten"); await File.WriteAllTextAsync(file, original.Replace("synthetic-user", "other-user")); await Expect("DRIVE_SCOPE_MISMATCH", () => Task.Run(() => new DriveListingCache(dir, Scope, Fake()))); });
        await Test("fixture disconnected folders and cycles cannot escape selected root", async () => { var source = Fixture(); await Expect("DRIVE_FIXTURE_SCOPE", () => Task.Run(() => new OfflineDriveTransport(source with { Folders = source.Folders.Append(new(Scope, "unreachable", [])).ToArray() }, true))); await Expect("DRIVE_DUPLICATE", () => Task.Run(() => new OfflineDriveTransport(source with { Folders = [new(Scope, Scope.RootId, [new(Scope.RootId, "cycle", DriveEntry.FolderMime)])] }, true))); });
        await Test("explicit system init is idempotent and does not automatically run retention", async () => { var p = Fake(); var system = new OfflineDriveSystem(Scope, p, true); var first = await system.InitializeAsync(); var count = p.Mutations; var second = await system.InitializeAsync(); Assert(first == second && p.Mutations == count && count == 2, "Init non-idempotent or unexpected cleanup"); var listing = await p.ListAsync(Scope, "hidden", default); Assert(listing.Entries.Count == 2, "System tree incorrect"); });
        await Test("system log/action require ready state and use bounded metadata with unique IDs", async () => { var p = Fake(); var system = new OfflineDriveSystem(Scope, p, true); await Expect("DRIVE_SYSTEM_NOT_INITIALIZED", () => system.SaveActionLogAsync("CREATE", "projects", "item")); var f = await system.InitializeAsync(); var a = await system.SaveActionLogAsync("CREATE", "projects", "item"); var b = await system.SaveActionLogAsync("UPDATE", "projects", "item"); Assert(a.Id != b.Id && (await p.ListAsync(Scope, f.JsonId, default)).Entries.Count == 2, "Log IDs collide"); await Expect("DRIVE_ACTION", () => system.SaveActionLogAsync("EXECUTE", "projects", "item")); await Expect("DRIVE_LOG_LABEL", () => system.SaveJsonLogAsync("../secret", JsonSerializer.SerializeToElement(new { x = 1 }))); });
        await Test("resource compensation removes only operation-owned upload on commit failure", async () => { var p = Fake(); var system = new OfflineDriveSystem(Scope, p, true); var f = await system.InitializeAsync(); var retained = await system.UploadResourceWithCommitAsync("first.txt", [1, 2], "text/plain", (_, _) => Task.CompletedTask); try { await system.UploadResourceWithCommitAsync("second.txt", [3], "text/plain", (_, _) => Task.FromException(new IOException("commit failed"))); } catch (IOException) { } var entries = (await p.ListAsync(Scope, f.ResourcesId, default)).Entries; Assert(entries.Count == 1 && entries[0].Id == retained.Id && p.ReadContent(Scope, retained.Id).SequenceEqual(new byte[] { 1, 2 }), "Compensation damaged existing resource"); await Expect("DRIVE_RESOURCE_NAME", () => system.UploadResourceWithCommitAsync("../bad", [], "text/plain", (_, _) => Task.CompletedTask)); });
        await Test("retention previews exact old JSON only and preserves member logs resources and new logs", async () => { var old = DateTimeOffset.UtcNow.AddDays(-10); var entries = new[] { new DriveEntry("old", "projects_old.json", "application/json", 3, old), new DriveEntry("member", "회원관리_old.json", "application/json", 3, old), new DriveEntry("resource", "drawing.png", "image/png", 3, old), new DriveEntry("new", "projects_new.json", "application/json", 3, DateTimeOffset.UtcNow) }; var fixture = new OfflineDriveFixture(1, Scope, [new(Scope, Scope.RootId, [new("sys", ".system", DriveEntry.FolderMime)]), new(Scope, "sys", [new("json", "json", DriveEntry.FolderMime), new("res", "resouces", DriveEntry.FolderMime)]), new(Scope, "json", entries), new(Scope, "res", [])]); var p = new OfflineDriveTransport(fixture, true); var system = new OfflineDriveSystem(Scope, p, true); await system.InitializeAsync(); Assert(p.Mutations == 0, "Init renamed legacy resources typo"); var plan = await system.PreviewRetentionAsync(DateTimeOffset.UtcNow); Assert(plan.Entries.Count == 1 && plan.Entries[0].Id == "old" && p.Mutations == 0, "Preview mutated or selected wrong rows"); await Expect("DRIVE_RETENTION_CONFIRM", () => system.ApplyRetentionAsync(plan, false)); Assert(await system.ApplyRetentionAsync(plan, true) == 1 && (await p.ListAsync(Scope, "json", default)).Entries.Count == 3, "Retention did not protect excluded rows"); await Expect("DRIVE_RETENTION_STALE", () => system.ApplyRetentionAsync(plan, true)); });
        await Test("retention forged scope or newer candidate is blocked before deletion", async () => { var p = Fake(); var system = new OfflineDriveSystem(Scope, p, true); var f = await system.InitializeAsync(); var entry = await system.SaveActionLogAsync("CREATE", "projects", "item"); var before = p.Mutations; var plan = new DriveRetentionPlan(Scope, f.JsonId, DateTimeOffset.UtcNow.AddDays(-7), [entry]); await Expect("DRIVE_RETENTION_STALE", () => system.ApplyRetentionAsync(plan, true)); await Expect("DRIVE_SCOPE_MISMATCH", () => system.ApplyRetentionAsync(plan with { Scope = Scope with { ProjectId = "foreign" } }, true)); Assert(before == p.Mutations, "Invalid retention mutated fixture"); });
        await Test("mutating caller byte arrays and cache snapshots does not change stored originals", async () => { var p = Fake(); var system = new OfflineDriveSystem(Scope, p, true); await system.InitializeAsync(); byte[] bytes = [1, 2]; var created = await system.UploadResourceWithCommitAsync("asset.bin", bytes, "application/octet-stream", (_, _) => Task.CompletedTask); bytes[0] = 9; var fetched = p.ReadContent(Scope, created.Id); fetched[0] = 8; Assert(p.ReadContent(Scope, created.Id)[0] == 1, "Mutable bytes leaked"); using var cache = new DriveListingCache(Folder(), Scope, p); await cache.WarmAsync(); var snapshot = cache.ReadSnapshot(); ((DriveEntry[])snapshot[0].Entries)[0] = new("wrong", "changed", "text/plain"); Assert(cache.ReadSnapshot().All(x => x.Entries.All(e => e.Id != "wrong")), "Mutable snapshot changed cache"); });
        await Test("dispose cancels owned warm and retains last durable cache", async () => { var dir = Folder(); var p = Fake(); var cache = new DriveListingCache(dir, Scope, p); await cache.WarmAsync(); var before = File.ReadAllBytes(cache.CacheFile); var entered = new TaskCompletionSource(); p.BeforeList = async (_, ct) => { entered.TrySetResult(); await Task.Delay(Timeout.Infinite, ct); }; var warm = cache.WarmAsync(true); await entered.Task; cache.Dispose(); await Cancelled(warm); Assert(File.ReadAllBytes(cache.CacheFile).SequenceEqual(before), "Dispose changed durable cache"); });
        var summary = new { roadmap = "70", pass, fail, work, tests = results, networkCalls = 0, realDriveAdapter = "NotConfigured", scope = "Isolated synthetic fixture listing cache/system only; no company auth or cloud writes", reportReady = false, supervisorAccepted = false }; await File.WriteAllTextAsync(Path.Combine(work, "RESULT.json"), JsonSerializer.Serialize(summary, new JsonSerializerOptions { WriteIndented = true })); Console.WriteLine($"DRIVE70 pass={pass} fail={fail} evidence={work}"); return fail == 0 ? 0 : 1;
    }
    sealed class NonFixture : IOfflineDriveSystemTransport { public bool IsSynthetic => false; public Task<DriveListing> ListAsync(DriveScope s, string f, CancellationToken ct) => throw new NotSupportedException(); public Task<DriveEntry> CreateFolderAsync(DriveScope s, string f, string n, CancellationToken ct) => throw new NotSupportedException(); public Task<DriveEntry> UploadAsync(DriveScope s, string f, string n, byte[] b, string m, CancellationToken ct) => throw new NotSupportedException(); public Task TrashAsync(DriveScope s, string id, CancellationToken ct) => throw new NotSupportedException(); }
    sealed class WrongScope : IDriveListingProvider { public bool IsSynthetic => true; public Task<DriveListing> ListAsync(DriveScope s, string f, CancellationToken ct) => Task.FromResult(new DriveListing(s with { UserId = "wrong" }, f, [])); }
    sealed class DuplicateProvider : IDriveListingProvider { public bool IsSynthetic => true; public Task<DriveListing> ListAsync(DriveScope s, string f, CancellationToken ct) => Task.FromResult(new DriveListing(s, f, [new("same", "a", "text/plain"), new("same", "b", "text/plain")])); }
}
